// Uniform Initialization Syntax (C++11)
int a = 1;      // Traditional
int b(2);       // Direct initialization
int c{3};       // Uniform syntax (safe against narrowing)
auto d{4};      // Type deduction

// std::initializer_list
void func(std::initializer_list<int> l) {
    for (int x : l) { /* ... */ }
}
func({1, 2, 3});

// Aggregate Initialization (Structs/Arrays)
struct Point { int x, y; };
Point p1 = {10, 20};     // Aggregate initialization
Point p2{};              // Default initialization (p2.x=0, p2.y=0)

int arr[] = {1, 2, 3};
int arr2[5] = {1, 2};    // arr2[2..4] initialized to zero

// Class with Initializer List Constructor
class ListContainer {
public:
    std::vector<int> data;
    ListContainer(std::initializer_list<int> l) : data(l) {}
};
ListContainer lc = {10, 20, 30};
